"""Analyse a CSV file.

The lesson here: do the arithmetic in Python, and let the AI do the reading.
Sending 40,000 rows and asking "what is the total" is slow, expensive and wrong.
Computing the total yourself and asking "what does this pattern mean" is fast,
cheap and right.
"""

from __future__ import annotations

import csv
import statistics
from pathlib import Path
from typing import Any

from .core import ask

INSIGHT_SCHEMA = {
    "type": "object",
    "properties": {
        "headline": {"type": "string"},
        "findings": {"type": "array", "items": {"type": "string"}},
        "anomalies": {"type": "array", "items": {"type": "string"}},
        "next_checks": {"type": "array", "items": {"type": "string"}},
    },
    "required": ["headline", "findings", "anomalies", "next_checks"],
    "additionalProperties": False,
}


def profile(path: Path) -> dict[str, Any]:
    """Describe a CSV without an AI: shape, types, ranges, gaps."""
    rows = list(csv.DictReader(Path(path).open(encoding="utf-8-sig", newline="")))
    if not rows:
        return {"row_count": 0, "columns": {}}

    columns: dict[str, Any] = {}
    for name in rows[0]:
        values = [r.get(name, "") for r in rows]
        filled = [v for v in values if v not in ("", None)]
        numbers: list[float] = []
        for v in filled:
            try:
                numbers.append(float(v))
            except (TypeError, ValueError):
                pass

        info: dict[str, Any] = {
            "missing": len(values) - len(filled),
            "distinct": len(set(filled)),
        }
        if numbers and len(numbers) == len(filled):
            info["kind"] = "number"
            info["min"] = min(numbers)
            info["max"] = max(numbers)
            info["mean"] = round(statistics.fmean(numbers), 4)
            if len(numbers) > 1:
                info["stdev"] = round(statistics.stdev(numbers), 4)
                odd = _outliers(numbers)
                info["outliers"] = len(odd)
                info["outlier_values"] = odd[:5]
        else:
            info["kind"] = "text"
            counts: dict[str, int] = {}
            for v in filled:
                counts[v] = counts.get(v, 0) + 1
            info["top"] = sorted(counts.items(), key=lambda kv: -kv[1])[:5]
        columns[name] = info

    return {"row_count": len(rows), "columns": columns, "sample": rows[:5]}


def _outliers(numbers: list[float]) -> list[float]:
    """Values far outside the middle half of the data (the 1.5 x IQR rule).

    Worth doing in Python: a language model shown only a min, a max and a mean
    will call a spike 'variability' and move on. Handing it the actual odd
    values is the difference between a vague answer and a useful one.
    """
    if len(numbers) < 4:
        return []
    ordered = sorted(numbers)
    q1 = statistics.median(ordered[: len(ordered) // 2])
    q3 = statistics.median(ordered[(len(ordered) + 1) // 2 :])
    gap = q3 - q1
    if gap == 0:
        return []
    low, high = q1 - 1.5 * gap, q3 + 1.5 * gap
    odd = {n for n in numbers if n < low or n > high}
    return sorted(odd)


def analyse_data(path: Path, question: str | None = None) -> dict:
    facts = profile(path)
    instruction = question or (
        "You are a data analyst. You are given a computed profile of a dataset, "
        "not the raw rows. Explain what it shows. State a number only if it "
        "appears in the profile. If something cannot be concluded, say so."
    )
    result = ask(instruction, _render(facts), schema=INSIGHT_SCHEMA)
    assert isinstance(result, dict)
    result["_profile"] = facts
    return result


def _render(facts: dict[str, Any]) -> str:
    lines = [f"Rows: {facts['row_count']}", "", "Columns:"]
    for name, info in facts["columns"].items():
        bits = [f"kind={info['kind']}", f"missing={info['missing']}", f"distinct={info['distinct']}"]
        for key in ("min", "max", "mean", "stdev"):
            if key in info:
                bits.append(f"{key}={info[key]}")
        if info.get("outlier_values"):
            bits.append("unusual_values=" + ", ".join(str(v) for v in info["outlier_values"]))
        if "top" in info:
            bits.append("top=" + ", ".join(f"{v}({c})" for v, c in info["top"]))
        lines.append(f"  {name}: " + "  ".join(bits))
    lines += ["", "First rows:"]
    for row in facts.get("sample", []):
        lines.append("  " + " | ".join(f"{k}={v}" for k, v in row.items()))
    return "\n".join(lines)
